function playbook(){ var tips=[
  ["📊 Find the cheapest marks first","In CBSE papers, a few high-weight chapters carry most of the marks. Fix weak A-priority chapters before polishing strong ones. 40% → 70% in one chapter beats 85% → 90% in another."],
  ["📗 NCERT first, always","Most board questions come straight from NCERT text, examples, in-text questions and exercises. A weak student should finish NCERT exercises before any guide book."],
  ["🗂 Previous-year and sample papers","From 6–8 weeks before the exam, do the last 5 years' questions chapter-wise, then full CBSE sample papers. Patterns repeat."],
  ["⏱ Timed practice every week","One timed mock a week on paper (photos uploaded). Students lose marks on time, not just knowledge. Review the mistakes in the next class."],
  ["✍️ Teach how to write answers","Formula first, every step on a new line, units, underline the final answer, labelled diagrams, keywords from NCERT, points instead of paragraphs for 3–5 markers. Step marks save weak students."],
  ["🔁 Little and often beats long and rare","20 minutes every day (daily quiz + one topic) is better than 3 hours on Sunday. Watch the daily-quiz count on this page."],
  ["🧠 Mistake notebook","Every wrong answer goes into a notebook with the correct method. Revise it before every test — the same mistakes stop coming back."],
  ["📞 Parents as partners","Send the parent one honest, positive message a week with one thing to do at home (fixed study time, phone away). Use the message above."],
  ["🏆 Praise effort, publicly and specifically","“You did the quiz 6 days this week” works better than “good job”. Praise strengths shown above before talking about weak areas."],
  ["🎯 Full-marks students","For students already above 85%: HOTS and case-based questions, competency questions from the CBSE question bank, and zero careless mistakes — check presentation and units."]];
  return '<details class="card" style="margin-top:12px"><summary style="cursor:pointer;font-weight:700">📘 Tutor playbook — 10 proven ways to raise marks</summary><div class="stack" style="gap:8px;margin-top:10px">'+tips.map(function(t){ return '<div><b>'+t[0]+'</b><div class="small">'+t[1]+'</div></div>'; }).join("")+'</div></details>'; }
