// ----- 🤖 Agent status (owner only): a free check (no AI call) every 10 min; tap = full test -----
var AIC={t:null};
function aiChip(){ var b=$("tAI"); if(!b) return; if(lsGet("ek_owner")==="0"){ b.classList.add("hidden"); return; } b.classList.remove("hidden");
  var paint=function(d){ var ok=!d.resting && d.keys>0; b.textContent= !d.keys? "🔴 Agent: no key" : d.resting? "🟠 Agent resting" : "🟢 Agent ready"; b.style.background= ok? "rgba(34,197,94,.18)" : "rgba(245,158,11,.22)";
    b.title= (d.resting? "Free limit was reached "+(d.restMin||0)+" min ago — students may see \"busy\". ":"Ekanthi Agent looks OK. ")+"Keys: "+d.keys+"/3 · Backup: "+(d.workersAI?"on":"off")+". Tap to run a real test."; };
  var load=function(){ api("/api/admin/ai-status").then(paint).catch(function(){ b.textContent="🤖 ?"; }); }; load(); clearInterval(AIC.t); AIC.t=setInterval(load, 600000);
  b.onclick=function(){ var w=document.createElement("div"); w.className="modal"; w.innerHTML='<div class="card" style="max-width:520px;width:94%;max-height:86vh;overflow:auto"><div class="row between"><h2>🤖 Ekanthi Agent test</h2><button class="btn ghost sm" data-x>✕</button></div><div id="aicOut" style="margin-top:8px"><span class="spinner"></span> Testing…</div></div>';
    w.onclick=function(e){ if(e.target===w||e.target.closest("[data-x]")) w.remove(); }; document.body.appendChild(w);
    api("/api/admin/aitest").then(function(r){ var o=$("aicOut"); if(!o) return;
      o.innerHTML=(r.ok? '<div class="card" style="background:#f0fdf4;border-color:#bbf7d0">✅ <b>Working</b> — students can use notes, questions and doubts.</div>' : '<div class="card" style="background:#fff7ed;border-color:#fed7aa">⚠️ <b>Not working right now</b> — '+esc(r.error||"")+'</div>')+
        '<div class="small" style="margin-top:8px">🔑 Gemini keys: <b>'+(r.keys||0)+'</b> / 3 · 🛟 Backup (Workers AI): <b>'+(r.workersAI?'on':'off')+'</b></div>'+
        ((r.trace||[]).length? '<table style="margin-top:8px"><tbody>'+r.trace.map(function(t){ return '<tr><td class="small">'+esc(t.model)+'</td><td class="small">'+(t.status===200?'✅':'⛔ '+t.status)+'</td><td class="small muted">'+esc(t.status===200?'OK':(t.status===429?'free limit reached':t.message||''))+'</td></tr>'; }).join("")+'</tbody></table>':'')+
        (!r.ok? '<div class="small muted" style="margin-top:8px">Free limits reset daily (about 11 AM–12 PM Oman time). To avoid this: add GEMINI_API_KEY_2 / _3 (keys from other Google accounts) and the Workers AI binding “AI” in Cloudflare.</div>':''); load(); })
    .catch(function(e){ var o=$("aicOut"); if(o) o.innerHTML='<div class="muted">'+esc(e.message)+'</div>'; }); }; }
