    '<div><label class="f">Username</label><input id="peUser" type="text" value="'+esc(p.username)+'" placeholder="'+(isNew?'auto: p.&lt;child username&gt;':'')+'"></div><div><label class="f">'+(isNew?'Password (optional — leave empty for a random one)':'New password (leave empty to keep)')+'</label><input id="pePin" type="text" maxlength="20" placeholder="4–20 letters / numbers"></div></div>'+
    '<label class="f" style="margin-top:8px">Children <span class="muted small">(tick brothers / sisters too)</span></label><div class="dev-chips">'+studs.map(function(x){ return '<label class="dev-chip'+(p.student_ids.indexOf(x.id)>=0?' on':'')+'" style="cursor:pointer"><input type="checkbox" data-pek="'+x.id+'" style="width:auto;margin-right:4px"'+(p.student_ids.indexOf(x.id)>=0?' checked':'')+'>'+esc(x.name)+'</label>'; }).join("")+'</div>'+
    '<div class="grid2" style="margin-top:8px"><div><label class="f">Language</label><select id="peLang">'+["en","ml","hi"].map(function(l){ return '<option value="'+l+'"'+(p.lang===l?' selected':'')+'>'+PLANG[l]+'</option>'; }).join("")+'</select></div><div><label class="f">Plan</label><select id="peTier"><option value="basic">Basic</option><option value="pro"'+(p.tier==="pro"?' selected':'')+'>⭐ Pro — all Pro parent features</option></select></div></div>'+
    '<div class="card" style="margin-top:10px;background:#fafbfd"><div class="row between"><b>🎛️ Features for this parent</b><button type="button" class="btn ghost sm" id="peFReset">All default</button></div><div class="small muted" style="margin:2px 0 6px">“Default” follows the plan above and the 🎛️ Parent features table. ✅ On / ⛔ Off is only for this parent.</div><div id="peFeats"></div></div>'+
    (isNew?'':'<div class="card" style="margin-top:10px;background:'+(p.active?'#fafbfd':'#fdecec')+'"><label style="display:flex;gap:6px;align-items:center"><input type="checkbox" id="peLock" style="width:auto"'+(p.active?'':' checked')+'> 🔒 Lock this parent account</label><label class="f" style="margin-top:6px">Message shown when they try to log in</label><input id="peLockMsg" type="text" maxlength="300" value="'+esc(p.lock_msg||"")+'" placeholder="e.g. Fees pending — please contact Ma\'am"></div>')+
    '<div class="row" style="gap:8px;margin-top:12px;justify-content:flex-end"><button class="btn ghost sm" data-x>Cancel</button><button class="btn sm" id="peSave">'+(isNew?'Create login':'Save')+'</button></div><div id="peOut"></div></div>';
