    var ia=d.impAnswers||[];
    body+='<h3 style="margin:16px 0 8px">Important-question answers</h3>'+(ia.length? '<div class="card scroll"><table><thead><tr><th>Date</th><th>Chapter</th><th>Question</th><th>Marks</th><th>Feedback</th></tr></thead><tbody>'+ia.map(function(x){ return '<tr><td>'+fmtDate(x.date)+'</td><td class="small">'+esc(x.chapter||"")+'</td><td class="small">'+esc((x.q||"").slice(0,120))+'</td><td><span class="pill '+(x.marks>=x.max_marks?'good':x.marks>=x.max_marks/2?'p1':'alert')+'">'+x.marks+'/'+x.max_marks+'</span>'+(x.photo?' 📷':'')+'</td><td class="small">'+esc((x.feedback||"").slice(0,200))+'</td></tr>'; }).join("")+'</tbody></table></div>' : '<div class="card empty">No answers checked yet.</div>');
