// ----- owner: syllabus topics per chapter (the AI only asks from these) -----
function sylTopics(sid, sname){ var m=$("sylDlg"); if(m) m.remove(); m=document.createElement("div"); m.className="modal"; m.id="sylDlg";
  m.innerHTML='<div class="box" style="max-width:760px;width:96vw;max-height:90vh;overflow:auto;text-align:left;padding:18px;background:#fff;color:var(--ink)"><div class="row between"><h2>📚 '+esc(sname)+' — syllabus topics</h2><button class="btn ghost sm" data-x>✕</button></div><div class="muted small" style="margin:4px 0 10px">Every question, note and answer for a chapter is kept inside these topics. Built-in topics are shown grey (Class 9 Maths 2026-27); empty chapters are looked up on the web automatically — check and correct them here.</div><div id="sylBody"><div class="card empty"><span class="spinner"></span></div></div></div>';
  document.body.appendChild(m); m.addEventListener("click", function(e){ if(e.target===m||e.target.closest("[data-x]")) m.remove(); });
  var draw=function(d){ $("sylBody").innerHTML=d.chapters.map(function(c){ return '<div style="margin-bottom:12px"><b>'+esc(c.name)+'</b>'+(c.builtin?' <span class="pill p0">built-in</span>':'')+'<textarea data-syl="'+c.id+'" rows="2" style="margin-top:4px" placeholder="'+esc(c.builtin||"Topics covered, comma separated — empty = looked up automatically")+'">'+esc(c.topics)+'</textarea></div>'; }).join("")+'<div class="row" style="gap:8px"><button class="btn" id="sylSave">Save</button><button class="btn ghost" id="sylFill">🔎 Look up empty chapters on the web</button></div>';
    $("sylSave").onclick=function(){ var b=this; b.disabled=true; var list=[].slice.call(m.querySelectorAll("[data-syl]")); var go=function(i){ if(i>=list.length){ toast("✅ Saved"); b.disabled=false; return; } var t=list[i]; api("/api/admin/chapter/topics",{subject_id:sid, id:Number(t.dataset.syl), topics:t.value}).then(function(){ go(i+1); }).catch(function(e){ toast(e.message); b.disabled=false; }); }; go(0); };
    $("sylFill").onclick=function(){ var b=this; b.disabled=true; b.innerHTML='<span class="spinner"></span> Looking up (up to 6 chapters)…'; api("/api/admin/chapter/topics",{subject_id:sid, fill:true}).then(draw).catch(function(e){ toast(e.message); b.disabled=false; b.textContent="🔎 Try again"; }); }; };
  api("/api/admin/chapter/topics?subject_id="+sid).then(draw).catch(function(e){ $("sylBody").innerHTML='<div class="card empty">'+esc(e.message)+'</div>'; }); }
window.sylTopics=sylTopics;
function sylAll(btn){ btn.disabled=true; var done=0, tried=0;
  var step=function(){ api("/api/admin/chapter/topics-all",{}).then(function(r){ done+=r.done; tried+=r.tried; var n=$("sylAllNote"); if(n) n.innerHTML='<span class="spinner"></span> '+done+' chapters updated · '+r.remaining+' left (of '+r.total+')';
      if(r.remaining>0 && r.tried>0 && $("sylAll")) setTimeout(step, 400); else { btn.disabled=false; if(n) n.textContent='✅ Done — '+done+' chapters updated'+(tried-done?' · '+(tried-done)+' not found (open 📚 Syllabus topics to add them by hand)':'')+'. New questions now follow these topics.'; } })
    .catch(function(e){ btn.disabled=false; toast(e.message); }); };
  step(); }

