// pages: blocks separated by a line with ---. "img: https://…" adds a picture, "pic: 🐢" a big emoji.
function bkPagesTxt(P){ return (P||[]).map(function(p){ return (p.h?"title: "+p.h+"\n":"")+(p.img?"img: "+p.img+"\n":"")+(p.e?"pic: "+p.e+"\n":"")+(p.t||"")+(p.f?"\nfact: "+p.f:""); }).join("\n---\n"); }
function bkPagesParse(s){ return String(s||"").split(/\n\s*---+\s*\n/).map(function(blk){ var o={t:""}, lines=[]; blk.split("\n").forEach(function(l){ var m=l.match(/^\s*img:\s*(\S+)/i), e=l.match(/^\s*pic:\s*(.+)$/i), hh=l.match(/^\s*title:\s*(.+)$/i), ff=l.match(/^\s*fact:\s*(.+)$/i); if(m) o.img=m[1]; else if(e) o.e=e[1].trim(); else if(hh) o.h=hh[1].trim(); else if(ff) o.f=ff[1].trim(); else lines.push(l); }); o.t=lines.join("\n").trim(); return o; }).filter(function(p){ return p.t||p.img||p.e; }); }
// quiz: one question per line — Question? | wrong | *right | wrong
function bkQuizTxt(Q){ return (Q||[]).map(function(q){ return q.q+" | "+q.o.map(function(o,i){ return (i===q.a?"*":"")+o; }).join(" | "); }).join("\n"); }
function bkQuizParse(s){ return String(s||"").split("\n").map(function(l){ var p=l.split("|").map(function(x){ return x.trim(); }).filter(Boolean); if(p.length<3) return null; var a=0, o=p.slice(1).map(function(x,i){ if(x[0]==="*"){ a=i; return x.slice(1).trim(); } return x; }); return {q:p[0], o:o, a:a}; }).filter(Boolean); }
