document.addEventListener("click", function(e){ var b=e.target.closest && e.target.closest("[data-pact]"); if(b) paActivity(Number(b.dataset.pact)); });
function paActivity(id){ var w=ekSheet('<div class="empty"><span class="spinner"></span></div>',"paAct");
  api("/api/admin/parent/activity?id="+id).then(function(d){ var P=d.parent, L=d.last30||{}, KN={login:["🔓","Logged in","#1f8a5b"],logout:["🚪","Logged out","#5b6472"],open:["📱","Opened the app","#1d4f80"],view:["👀","Looked at","#1d4f80"],fail:["❌","Wrong password","#c0392b"],blocked:["🔒","Tried while locked","#c0392b"]};
    var h='<h2 style="margin:0 0 2px">📋 '+esc(P.name)+'</h2><div class="small muted" style="margin-bottom:10px"><code>'+esc(P.username)+'</code> · '+(P.active?'active':'<b style="color:#c0392b">locked</b>')+(P.last_login?' · last login '+fmtDT(P.last_login):'')+' · '+(P.logins||0)+' logins in total</div>';
    h+='<div class="tstats" style="margin-bottom:10px;display:grid;grid-template-columns:repeat(2,1fr);gap:8px">'+[["🔓",L.logins,"logins"],["📱",L.opens,"app opens"],["👀",L.views,"child views"],["❌",L.fails,"wrong tries"]].map(function(x){ return '<div class="ts"><div class="ts-n">'+x[0]+' '+(x[1]||0)+'</div><div class="ts-l">'+x[2]+' · 30 days</div></div>'; }).join("")+'</div>';
    h+='<h3 style="margin:8px 0 4px">📲 Devices</h3>'+(d.devices.length? d.devices.map(function(v){ return '<div class="small" style="padding:6px 0;border-bottom:1px solid var(--line)"><b>'+esc(uaShort(v.ua)||"Device")+'</b>'+(v.country?' · '+esc(v.country):'')+' · '+v.n+' times · last '+fmtDT(v.last)+'</div>'; }).join("") : '<div class="small muted">No device seen yet.</div>');
    if(d.fails.length) h+='<h3 style="margin:12px 0 4px;color:#c0392b">❌ Wrong passwords (30 days)</h3>'+d.fails.map(function(f){ return '<div class="small" style="padding:4px 0">'+fmtDT(f.at)+' · '+esc(uaShort(f.ua)||"Device")+(f.country?' · '+esc(f.country):'')+'</div>'; }).join("");
    h+='<h3 style="margin:12px 0 4px">🕒 Timeline</h3>'+(d.events.length? '<div class="scroll" style="max-height:340px;overflow:auto">'+d.events.map(function(e){ var k=KN[e.kind]||["•",e.kind,"#5b6472"]; return '<div class="row" style="gap:10px;padding:7px 0;border-bottom:1px solid var(--line);align-items:flex-start"><span style="font-size:18px">'+k[0]+'</span><span style="flex:1"><b style="color:'+k[2]+'">'+k[1]+(e.kind==="view"&&e.detail?' '+esc(e.detail):'')+'</b>'+(e.kind!=="view"&&e.kind!=="fail"&&e.detail?'<div class="small muted">'+esc(e.detail)+'</div>':'')+'<div class="small muted">'+esc(uaShort(e.ua)||"")+(e.country?' · '+esc(e.country):'')+'</div></span><span class="small muted" style="white-space:nowrap">'+fmtDT(e.at)+'</span></div>'; }).join("")+'</div>' : '<div class="small muted">Nothing recorded yet. Activity is recorded from this update on.</div>');
    h+='<button class="btn ghost block" data-x style="margin-top:12px">Close</button>';
    w.querySelector(".in").innerHTML=h;
  }).catch(function(e){ w.querySelector(".in").innerHTML='<div class="empty">'+esc(e.message)+'</div><button class="btn ghost block" data-x>Close</button>'; }); }
function stuEdit(a){ var m=$("stuEd"); if(m) m.remove(); m=document.createElement("div"); m.className="modal"; m.id="stuEd";
  m.innerHTML='<div class="box" style="max-width:560px;width:94vw;max-height:90vh;overflow:auto;text-align:left;padding:18px;background:#fff;color:var(--ink)"><div class="row between"><h2>✏️ Edit student</h2><button class="btn ghost sm" data-x>✕</button></div>'+
    '<label class="f" style="margin-top:10px">Full name</label><input id="seName" type="text" maxlength="80" value="'+esc(a.name)+'" placeholder="e.g. Arhan Mohammed">'+
    '<label class="f" style="margin-top:10px">Username (for login)</label><input id="seUser" type="text" maxlength="24" value="'+esc(a.username)+'" autocapitalize="none" spellcheck="false"><div class="small muted">3–24 small letters / numbers / . or _ — no spaces. If you change it, tell the student the new username.</div>'+
    '<div class="grid2" style="margin-top:10px"><div><label class="f">Student phone</label><input id="sePh" type="tel" value="'+esc(a.phone||"")+'" placeholder="+968…"></div><div><label class="f">Parent phone</label><input id="sePp" type="tel" value="'+esc(a.parent_phone||"")+'" placeholder="+968…"></div></div>'+
    (a.subjChoice&&a.subjChoice.all.length?'<label class="f" style="margin-top:12px">📚 Subjects this student takes</label><div class="small muted" style="margin-bottom:4px">Untick a subject to hide it (study, quiz, mock, homework). ⭐ = optional / skill subject — only ticked students get it.</div><div class="stack" style="gap:4px">'+a.subjChoice.all.map(function(x){ var on=a.subjChoice.picked.length?a.subjChoice.picked.indexOf(x.id)>=0:!x.optional; return '<label class="row" style="gap:8px;font-weight:500"><input type="checkbox" class="seSub" value="'+x.id+'"'+(on?' checked':'')+' style="width:auto"> '+esc(x.name)+(x.optional?' <span class="pill">⭐ optional</span>':'')+'</label>'; }).join("")+'</div>':'')+
    (a.subjChoice&&a.subjChoice.features?'<label class="f" style="margin-top:12px">⭐ Plan / add-ons</label><div class="small muted" style="margin-bottom:4px">Locked add-ons still show to the student with a 🔒 “Ask Ma\'am” button.</div><div class="row" style="gap:6px;margin-bottom:6px"><button type="button" class="btn ghost sm" data-plan="basic">Basic</button><button type="button" class="btn ghost sm" data-plan="standard">Standard</button><button type="button" class="btn ghost sm" data-plan="premium">Premium (all)</button></div><div class="stack" style="gap:4px">'+a.subjChoice.features.map(function(f){ var on=!a.subjChoice.featuresOn||a.subjChoice.featuresOn.indexOf(f.k)>=0; return '<label class="row" style="gap:8px;font-weight:500"><input type="checkbox" class="seFeat" value="'+f.k+'"'+(on?' checked':'')+' style="width:auto"> '+f.ic+' '+esc(f.name)+' <span class="muted small">— '+esc(f.desc)+'</span></label>'; }).join("")+'</div>':'')+
    (a.subjChoice&&a.subjChoice.skillsOn?'<label class="f" style="margin-top:12px">🧠 Skills this student can use</label><div class="small muted" style="margin-bottom:4px">The student and parents always see Skills; ticked ones open for practice (new ones get the default days and sessions per day — change them in Overview → 🧠 Skills).</div><div class="row" style="gap:12px;flex-wrap:wrap">'+[["abacus","🧮 Abacus"],["speed","⚡ Speed maths"],["english","🗣️ Spoken English"]].map(function(k){ return '<label class="row" style="gap:6px;font-weight:600"><input type="checkbox" class="seSk" value="'+k[0]+'"'+(a.subjChoice.skillsOn.indexOf(k[0])>=0?' checked':'')+' style="width:auto">'+k[1]+'</label>'; }).join("")+'</div>':'')+
    '<details style="margin-top:12px"><summary style="cursor:pointer;font-weight:700">🔑 Set a new PIN of my choice</summary><div class="small muted" style="margin:6px 0">PINs are stored locked (encrypted) — nobody, not even the owner, can see the current PIN. You can give a new one: 6 digits, not easy like 123456.</div><input id="sePin" type="text" inputmode="numeric" maxlength="6" placeholder="6-digit PIN" autocomplete="off"></details>'+
    '<span class="err" id="seErr"></span><div class="row" style="gap:8px;margin-top:14px"><button class="btn" id="seSave">Save</button><button class="btn ghost" data-x>Cancel</button></div></div>';
  document.body.appendChild(m); m.addEventListener("click", function(e){ if(e.target===m||e.target.closest("[data-x]")) m.remove(); });
  $("seSave").onclick=function(){ var b=this, body={id:a.id, name:$("seName").value.trim(), username:$("seUser").value.trim().toLowerCase(), phone:$("sePh").value.trim(), parent_phone:$("sePp").value.trim()}, pin=$("sePin").value.trim();
    if(!body.name){ $("seErr").textContent="Name can't be empty"; return; }
    if(a.subjChoice&&a.subjChoice.features){ var fs=[].slice.call(document.querySelectorAll(".seFeat")); var on=fs.filter(function(x){return x.checked;}).map(function(x){return x.value;}); body.features= on.length===fs.length? null : on; }
    if(a.subjChoice&&a.subjChoice.all.length){ var ch=[].slice.call(document.querySelectorAll(".seSub")).filter(function(x){return x.checked;}).map(function(x){return Number(x.value);}); if(!ch.length){ $("seErr").textContent="Tick at least one subject"; return; }
      var def=a.subjChoice.all.filter(function(x){return !x.optional;}).map(function(x){return x.id;}); body.subjects=(ch.length===def.length&&def.every(function(id){return ch.indexOf(id)>=0;}))?null:ch; }
    if(pin){ if(!/^\d{6}$/.test(pin)){ $("seErr").textContent="PIN must be exactly 6 digits"; return; } if(!confirm("Set this new PIN? The old PIN stops working and the student is signed out.")) return; body.set_pin=pin; }
    b.disabled=true; b.textContent="Saving…";
    var skP=Promise.resolve(); if(a.subjChoice&&a.subjChoice.skillsOn){ var skOn=[].slice.call(document.querySelectorAll(".seSk")).filter(function(x){return x.checked;}).map(function(x){return x.value;}); if(skOn.sort().join()!==a.subjChoice.skillsOn.slice().sort().join()) skP=api("/api/admin/student/skills",{id:a.id, skills:skOn}); }
    skP.then(function(){ return api("/api/admin/student/update", body); }).then(function(r){ m.remove(); if(r.pin){ T.newCreds={name:body.name, username:r.username||body.username, pin:r.pin}; } toast("✅ Saved"+(r.username&&r.username!==a.username?" — new username: "+r.username:"")); loadDetail(a.id); window.scrollTo(0,0); })
    .catch(function(e){ b.disabled=false; b.textContent="Save"; $("seErr").textContent=e.message; }); };
}
function subTakers(sid){ api("/api/admin/subject/students?subject_id="+sid).then(function(d){ var m=$("subTk"); if(m) m.remove(); m=document.createElement("div"); m.className="modal"; m.id="subTk";
  m.innerHTML='<div class="box" style="max-width:460px;width:94vw;text-align:left;padding:18px;background:#fff;color:var(--ink)"><div class="row between"><h2>👥 Who takes '+esc(d.subject.name)+'?</h2><button class="btn ghost sm" data-x>✕</button></div><div class="small muted" style="margin:6px 0">Ticked students see this subject in Study, quiz, mock and homework. Others don\'t.</div>'+
    (d.students.length?'<div class="stack" style="gap:4px;max-height:50vh;overflow:auto">'+d.students.map(function(x){ return '<label class="row" style="gap:8px;font-weight:500"><input type="checkbox" class="tkS" value="'+x.id+'"'+(x.takes?' checked':'')+' style="width:auto"> '+esc(x.name)+' <span class="muted small">@'+esc(x.username)+'</span></label>'; }).join("")+'</div>':'<div class="empty">No students in this class yet.</div>')+
    '<div class="row" style="gap:8px;margin-top:14px"><button class="btn" id="tkSave">Save</button><button class="btn ghost" data-x>Cancel</button></div></div>';
  document.body.appendChild(m); m.addEventListener("click", function(e){ if(e.target===m||e.target.closest("[data-x]")) m.remove(); });
  $("tkSave").onclick=function(){ var ids=[].slice.call(document.querySelectorAll(".tkS")).filter(function(x){return x.checked;}).map(function(x){return Number(x.value);});
    api("/api/admin/subject/students",{subject_id:sid, student_ids:ids}).then(function(r){ m.remove(); toast("✅ Saved — "+ids.length+" student(s) take "+d.subject.name); }).catch(function(e){ toast(e.message); }); };
}).catch(function(e){ toast(e.message); }); }
function renderClasses(){
  var cs=T.classes, c=cs.filter(function(x){return x.id===T.clsSel;})[0];
  var h='<div class="row between" style="margin-bottom:12px"><div class="subtabs">'+cs.map(function(x){return '<button data-cls="'+x.id+'" class="'+(x.id===T.clsSel?'on':'')+'">'+esc(x.board+" "+x.name)+' <span class="muted small">('+x.students+')</span></button>';}).join("")+'</div><div class="row" style="gap:6px"><button class="btn ghost sm" data-ca="loadsyl">📚 Load NCERT syllabus (Class 3–9)</button><button class="btn sm" data-ca="newclass">+ New class</button></div></div>';
  if(!c){ $("tMain").innerHTML=h+'<div class="card empty">No classes yet.</div>'; return; }
  h+='<div class="card stack"><h3>Class details</h3><div class="grid3"><div><label class="f">Name</label><input id="ccName" type="text" value="'+esc(c.name)+'"></div><div><label class="f">Board</label><input id="ccBoard" type="text" list="ccBoards" placeholder="CBSE / Kerala PSC / Railway" value="'+esc(c.board||"")+'"><datalist id="ccBoards"><option value="CBSE"><option value="Kerala PSC"><option value="Railway"><option value="SSC"></datalist><div class="small muted">Board “Kerala PSC”, “Railway” or “SSC” makes it an exam course (shown to exam candidates).</div></div><div><label class="f">Plan start (week 1 Monday)</label><input id="ccStart" type="date" value="'+esc(c.plan_start||"")+'"></div></div><div class="row"><button class="btn sm" data-ca="saveclass">Save class</button><button class="btn danger sm" data-ca="delclass">Delete class</button></div></div>';
  c.subjects.forEach(function(s){
    h+='<div class="card stack" style="margin-top:12px"><div class="grid3 inline" style="align-items:end"><div><label class="f">Subject</label><input type="text" data-sf="name" data-sid="'+s.id+'" value="'+esc(s.name)+'"></div><div><label class="f">Exam date</label><input type="date" data-sf="exam_date" data-sid="'+s.id+'" value="'+esc(s.exam_date||"")+'"></div><div class="row"><input type="color" data-sf="color" data-sid="'+s.id+'" value="'+esc(s.color||"#1f4e79")+'" style="width:46px;height:38px;padding:2px"><button class="btn ghost sm" data-ca="savesub" data-id="'+s.id+'">Save</button><label class="small row" style="gap:4px;font-weight:600" title="Optional = only the students you choose get this subject"><input type="checkbox" data-sf="optional" data-sid="'+s.id+'"'+(s.optional?' checked':'')+' style="width:auto"> ⭐ Optional</label><button class="btn ghost sm" data-ca="takers" data-id="'+s.id+'">👥 Students</button><button class="btn danger sm" data-ca="delsub" data-id="'+s.id+'">Delete</button></div><div class="row" style="gap:6px;margin-top:6px"><span class="small" style="flex:none">📖 Textbook link</span><input type="url" data-sf="book_url" data-sid="'+s.id+'" value="'+esc(s.book_url||"")+'" placeholder="https://ncert.nic.in/textbook.php?… (empty = NCERT link chosen by Ekanthi)" style="flex:1"></div></div>';
    h+='<div class="scroll"><table><thead><tr><th>Chapter</th><th>Priority</th><th>Week</th><th></th></tr></thead><tbody>'+s.chapters.map(function(ch){ return '<tr class="inline"><td><input type="text" data-cf="name" data-cid="'+ch.id+'" value="'+esc(ch.name)+'"></td><td style="width:90px"><select data-cf="priority" data-cid="'+ch.id+'">'+["A","B","C"].map(function(p){return '<option'+(p===ch.priority?' selected':'')+'>'+p+'</option>';}).join("")+'</select></td><td style="width:90px"><input type="number" min="1" max="60" data-cf="week" data-cid="'+ch.id+'" value="'+(ch.week||"")+'"></td><td style="width:50px"><button class="btn danger sm" data-ca="delch" data-id="'+ch.id+'">✕</button></td></tr>'; }).join("")+
      '<tr class="inline"><td><input type="text" id="nc-'+s.id+'" placeholder="New chapter name"></td><td><select id="ncp-'+s.id+'"><option>A</option><option selected>B</option><option>C</option></select></td><td><input type="number" id="ncw-'+s.id+'" min="1" max="60" placeholder="wk"></td><td><button class="btn sm" data-ca="addch" data-id="'+s.id+'">+</button></td></tr></tbody></table></div>';
    if(s.chapters.length) h+='<div><button class="btn ghost sm" onclick="sylTopics('+s.id+',\''+esc(s.name).replace(/'/g,"")+'\')">📚 Syllabus topics per chapter</button> <span class="muted small">Keeps AI questions inside the NCERT 2026-27 chapter.</span></div>';
    h+='<details'+(s.chapters.length?'':' open')+'><summary class="muted small" style="cursor:pointer">Paste many chapters at once</summary><div class="stack" style="margin-top:8px"><textarea id="bulk-'+s.id+'" placeholder="One chapter per line. Optional: Name | A | 3  (priority | week)"></textarea><div class="row"><button class="btn ghost sm" data-ca="bulk" data-id="'+s.id+'">Add all</button><button class="btn ghost sm" data-ca="suggest" data-id="'+s.id+'">✨ Suggest NCERT chapter list</button><button class="btn ghost sm" data-ca="warm" data-id="'+s.id+'" title="Make Ekanthi notes and important questions for every chapter now, so students never wait">⚡ Prepare all chapters</button><span class="muted small" id="sug-'+s.id+'">Check the suggestion with the textbook before adding.</span></div></div></details></div>';
  });
  if(/10/.test(c.name) && !c.subjects.some(function(x){return /artificial intelligence/i.test(x.name);})) h+='<div class="card row" style="margin-top:12px;gap:10px;flex-wrap:wrap"><button class="btn ghost sm" data-ca="skill" data-k="ai417">🤖 Add skill subject: Artificial Intelligence (417)</button><span class="muted small">CBSE Class 10 skill subject — only the students you choose will see it.</span></div>';
  h+='<div class="card row" style="margin-top:12px;gap:10px;flex-wrap:wrap"><button class="btn sm" id="sylAll">🔄 Update syllabus topics — all classes</button><span class="muted small" id="sylAllNote">Looks up the NCERT 2026-27 topics of every chapter that has none yet (Class 3–9 new books, Class 10 current books). Runs in small steps — keep this page open.</span></div>';
  h+='<div class="card row" style="margin-top:12px"><input id="nsubName" type="text" placeholder="New subject (e.g. English)" style="max-width:280px"><button class="btn ghost sm" data-ca="addsub">+ Add subject</button><span class="muted small">Languages:</span>'+["English","Hindi","Sanskrit","Malayalam"].filter(function(L){ return !c.subjects.some(function(x){return x.name.toLowerCase()===L.toLowerCase();}); }).map(function(L){ return '<button class="chip" data-ca="addlang" data-l="'+L+'">+ '+L+'</button>'; }).join("")+'</div>';
  $("tMain").innerHTML=h; var sa=$("sylAll"); if(sa) sa.onclick=function(){ sylAll(sa); };
}
function classClick(b){
  if(b.dataset.cls){ T.clsSel=Number(b.dataset.cls); renderClasses(); return; }
  var a=b.dataset.ca, id=Number(b.dataset.id); if(!a) return;
  var done=function(msg){ return function(){ toast(msg||"Saved"); loadClasses(); }; }, fail=function(e){ toast(e.message); };
  if(a==="loadsyl"){ if(!confirm("Add Class 3–9 with NCERT 2026-27 chapters (Maths, EVS/Science, Social Science)? Subjects that already have chapters are not changed.")) return;
    b.disabled=true; b.innerHTML='<span class="spinner"></span> Loading…';
    api("/api/admin/load-syllabus",{}).then(function(r){ alert("Done:\n\n"+r.log.join("\n")); loadClasses(); }).catch(fail); return; }
  if(a==="newclass"){ var trk=lsGet("ek_track")||"school", n=prompt(trk==="school"||trk==="all"?"New class name (e.g. Class 9)":"New course name (e.g. "+(trk==="psc"?"Kerala PSC — LDC":trk==="rail"?"RRB NTPC":"Bank PO")+")"); if(n) api("/api/admin/class/save",{name:n, board:TRACK_BOARD[trk]||"CBSE"}).then(function(){ api("/api/admin/classes").then(function(d){ T.classes=d.classes; var c=d.classes.filter(function(x){return x.name===n;}).pop(); if(c){ T.clsSel=c.id; } renderClasses(); }); }).catch(fail); }
  if(a==="saveclass") api("/api/admin/class/save",{id:T.clsSel, name:$("ccName").value, board:$("ccBoard").value, plan_start:$("ccStart").value}).then(done()).catch(fail);
  if(a==="delclass"){ if(confirm("Delete this class with all its subjects and chapters?")) api("/api/admin/class/delete",{id:T.clsSel}).then(done("Deleted")).catch(fail); }
  if(a==="savesub"){ var g=function(f){ return document.querySelector('[data-sf="'+f+'"][data-sid="'+id+'"]').value; }; api("/api/admin/subject/save",{id:id, name:g("name"), exam_date:g("exam_date"), color:g("color"), optional:document.querySelector('[data-sf="optional"][data-sid="'+id+'"]').checked, book_url:g("book_url")}).then(done()).catch(fail); }
  if(a==="takers"){ subTakers(id); return; }
  if(a==="skill"){ if(!confirm("Add the CBSE skill subject 'Artificial Intelligence (417)' to this class? 6 units from the CBSE AI Facilitator Handbook (Grade X) are added with their topics. It is ⭐ optional — then choose which students take it.")) return; b.disabled=true;
    api("/api/admin/skill-subject",{class_id:T.clsSel, key:b.dataset.k}).then(function(r){ toast("✅ Added"+(r.added?" — "+r.added+" units":"")+". Now pick the students."); loadClasses(); setTimeout(function(){ subTakers(r.subject_id); },600); }).catch(fail); return; }
  if(a==="delsub"){ if(confirm("Delete this subject and its chapters?")) api("/api/admin/subject/delete",{id:id}).then(done("Deleted")).catch(fail); }
  if(a==="addlang"){ api("/api/admin/subject/save",{class_id:T.clsSel, name:b.dataset.l}).then(done(b.dataset.l+" added — open it and paste or suggest chapters")).catch(fail); }
  if(a==="warm"){ var sj=null; T.classes.forEach(function(c){ c.subjects.forEach(function(x){ if(x.id===id) sj=x; }); }); if(!sj||!sj.chapters.length){ toast("No chapters yet"); return; }
    if(!confirm("Prepare Ekanthi notes + important questions for all "+sj.chapters.length+" chapters of "+sj.name+"? Takes about 30–40 sec per chapter — keep this page open.")) return;
    var list=sj.chapters.map(function(c){return c.id;}), k=0, fails=0; b.disabled=true;
    (function next(){ if(k>=list.length){ b.disabled=false; b.textContent="⚡ Prepared ✓"+(fails?" ("+fails+" retry)":""); toast(sj.name+": all chapters ready"); return; }
      b.innerHTML='<span class="spinner"></span> Preparing '+(k+1)+' / '+list.length;
      api("/api/admin/warm",{chapter_id:list[k]}).then(function(r){ if(r.done && r.done.some(function(x){return /fail/.test(x);})) fails++; }).catch(function(){ fails++; }).then(function(){ k++; next(); }); })();
    return; }
  if(a==="suggest"){ b.disabled=true; b.innerHTML='<span class="spinner"></span> Finding chapters…'; api("/api/admin/suggest-chapters",{subject_id:id}).then(function(r){ $("bulk-"+id).value=r.chapters.join("\n"); $("sug-"+id).textContent=(r.book?"Book: "+r.book+". ":"")+(r.note||"")+" — check with the textbook, edit, then Add all."; b.disabled=false; b.textContent="✨ Suggest again"; }).catch(function(e){ toast(e.message); b.disabled=false; b.textContent="✨ Suggest NCERT chapter list"; }); }
  if(a==="addsub"){ var sn=$("nsubName").value.trim(); if(sn) api("/api/admin/subject/save",{class_id:T.clsSel, name:sn}).then(done("Subject added")).catch(fail); }
  if(a==="addch"){ var nm=$("nc-"+id).value.trim(); if(nm) api("/api/admin/chapter/save",{subject_id:id, name:nm, priority:$("ncp-"+id).value, week:$("ncw-"+id).value}).then(done("Chapter added")).catch(fail); }
  if(a==="delch"){ if(confirm("Delete this chapter?")) api("/api/admin/chapter/delete",{id:id}).then(done("Deleted")).catch(fail); }
  if(a==="bulk"){ var tx=$("bulk-"+id).value; if(tx.trim()) api("/api/admin/chapters/bulk",{subject_id:id, text:tx}).then(function(r){ toast(r.added+" chapters added"); loadClasses(); }).catch(fail); }
}
