  h+='<div class="subtabs" style="margin-bottom:12px">'+c.subjects.map(function(x){return '<button data-smsubj="'+x.id+'" class="'+(x.id===SM.subj?'on':'')+'">'+esc(x.name)+'</button>';}).join("")+'</div>';
