      if(q.options) o+=q.options.map(function(op,j){ var c='opt'; if(pick===j) c+=' sel'; if(LP.key && j===q.answer) c+=' right'; return '<div class="'+c+'" style="cursor:default"><span class="l">'+"ABCD"[j]+'</span><span>'+esc(op)+'</span>'+(pick===j?' <span class="small" style="margin-left:auto">← '+esc(d.name.split(" ")[0])+'</span>':'')+'</div>'; }).join("");
