  var mb=document.querySelector("[data-mt]"); if(mb) mb.onclick=function(){ var on=mb.dataset.mt==="on"; if(on){ var w=d.online.length; if(!confirm((w?w+" student(s) are online now. ":"")+"Turn ON maintenance? Students will see “App is updating” until you turn it off.")) return; } api("/api/admin/maintenance",{on:on}).then(function(){ toast(on?"Maintenance ON":"Maintenance OFF — student apps will refresh"); loadLive(); }); };
