     '<div class="grid2"><div><label class="f">Date</label><input type="date" id="tcDate" value="'+d.today+'" max="'+d.today+'"></div><div><label class="f">Note (what you covered / homework)</label><input type="text" id="tcNote" placeholder="e.g. Examples 1–5 done, Ex 5.1 Q1–6 homework"></div></div>'+
     '<div class="row"><button class="btn" data-tcsave="1">✅ Save class (taught)</button><button class="btn ghost sm" data-tchw="1">📝 Give homework</button><span class="err" id="tcErr"></span></div></div>';
  // doubt
  var qa=(TC.qa[TC.ch]||[]);
