  var list=m.tracks.filter(function(t){ return t.k!=="exam" || t.classes>0; }), all={k:"all",ic:"🌐",l:"All",students:m.tracks.reduce(function(a,t){ return a+t.students; },0),pending:m.tracks.reduce(function(a,t){ return a+t.pending; },0),classes:1};
  b.innerHTML=[all].concat(list).map(function(t){ return '<button data-trk="'+t.k+'" class="'+(t.k===cur?'on':'')+'" title="'+(t.classes?t.classes+' class(es) / course(s)':'No courses yet — add one in Classes')+'">'+t.ic+' '+esc(t.l)+' <small>'+(t.classes?t.students:'+')+'</small>'+(t.pending?'<span class="pd">'+t.pending+'</span>':'')+'</button>'; }).join("");
  b.classList.remove("hidden");
